) {
    let block_header = data_column_sidecar.signed_block_header.message;
    if !self.store_snapshot().is_forward_synced()
        && self
            .store_snapshot()
            .accepted_data_column_sidecar(block_header, data_column_sidecar.index)
    {
        debug!(
